## Required types:

```typescript
// Impulse types
export interface Impulse {
  id: string
  pointer: ImpulsePointer
  budget: number
  priority: 'critical' | 'high' | 'medium' | 'low'
  loaded?: boolean
  content?: string
  tokenCount?: number
  tags?: string[]
  metadata?: Record<string, unknown>
}

export type ImpulsePointer =
  | { type: 'memo'; content: string }
  | { type: 'file'; path: string; offset?: number; limit?: number }
  | { type: 'custom'; resolver: string; data: Record<string, unknown> }

// Resolver interface
export interface Resolver {
  name: string
  enabled: boolean
  resolve(refs: ImpulseRef[], config: Record<string, unknown>): Promise<Impulse[]>
}

export interface ImpulseRef {
  id: string
  ref: string
  priority: 'required' | 'optional'
  budget: number
}

// Vessel configuration
export interface VesselConfig {
  name: string
  port: number
  workingDirectory: string
  resolvers: string[]
}
```

